playground.css:
body { font-family: system-ui, sans-serif; padding: 20px; background: #f8fafc; color: #0f172a; }
.app { max-width: 400px; display: grid; gap: 12px; }
.controls { display: flex; gap: 8px; }
input { flex: 1; padding: 8px 10px; border: 1px solid #cbd5e1; border-radius: 6px; }
button { padding: 8px 14px; border: none; border-radius: 6px; background: #2563eb; color: #fff; font-weight: 600; cursor: pointer; }
ul { list-style: none; padding: 0; margin: 0; display: grid; gap: 6px; }
li { padding: 8px 12px; background: #fff; border: 1px solid #e2e8f0; border-radius: 6px; cursor: pointer; }
li.done { text-decoration: line-through; color: #64748b; background: #f1f5f9; }

playground.js:
const input = document.getElementById('task-input');
const addBtn = document.getElementById('add-btn');
const list = document.getElementById('task-list');

function addTask() {
  const text = input.value.trim();
  if (!text) return;

  const li = document.createElement('li');
  li.textContent = text; // Seguro contra XSS!
  li.addEventListener('click', () => li.classList.toggle('done'));

  list.appendChild(li);
  console.log('Tarefa adicionada:', text);
  input.value = '';
  input.focus();
}

addBtn.addEventListener('click', addTask);
input.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') addTask();
});
